import json

def parse_ligand_data(json_data):
    """
    解析JSON格式的配体数据并格式化输出
    """
    ligands = json.loads(json_data)
    # save ligands to json file
    with open("ligands.json", "w") as f:
        # solve unicode error
        json.dump(ligands, f, indent=4, ensure_ascii=False)

